import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:65166');
await p.fill('#email','ops@lab.test');await p.fill('input[type=password]','lab-ops-pass');
await p.click('button');
for(let n=1;n<=3;n++){
 await p.goto('http://127.0.0.1:65166/refunds?page='+n);
 const ids=await p.$$eval('tbody tr',r=>r.map(x=>x.dataset.id));
 for(const id of ids){
  const row=p.locator(`tr[data-id="${id}"]`);
  const t=await row.innerText();const c=t.split('\t');
  if(!t.includes('Pending'))continue;
  const amt=+c[3].replace(/[^\d]/g,'');
  let act=null;
  if(t.includes('Blocked'))act='.rj';
  else if(c[2]==='Damaged item'&&amt<=500)act='.ap';
  if(act){await row.locator(act).click();await p.waitForTimeout(600);console.log(id,act,await row.innerText().catch(()=>'gone'));}
 }
}
await b.close();
